INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '0a5baeb1-e109-5c89-b733-fc60beb28f4d', '8f263c7b-e207-524d-a8fb-ff118fb23a3f',
  '1. Xây dựng bảng hash từ dãy các từ khóa $19, 14, 23, 1, 68, 20, 84, 27, 55, 11, 10, 79$, với hàm hash $H(key) = key \% 13$, sử dụng phương pháp danh sách liên kết (Linked list resolution) để giải quyết xung đột. Hãy cho biết có bao nhiêu phần tử trong danh sách liên kết ở địa chỉ 1. [5.3, 20]  
