);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '7823bc1b-32e4-5018-a862-a6f0ed6d272f', '8f263c7b-e207-524d-a8fb-ff118fb23a3f',
  '2. Giả sử bảng hash có không gian địa chỉ là $S[0..13]$, hàm $H(key) = key \% 11$, sử dụng phương pháp thăm dò bình phương (Quadratic probing) để giải quyết xung đột, trong bảng hash hiện đã có 4 khóa sau: 15, 38, 61, 84. Bây giờ chèn thêm khóa có giá trị 49 vào bảng hash, hãy cho biết khóa này sẽ được chèn vào địa chỉ nào. [5.2, 19]

Lựa chọn:
