- (b) 5
- (c) 8
- (d) 9', 2
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '19519394-c8ff-555a-a822-ebb6364e5373', '8f263c7b-e207-524d-a8fb-ff118fb23a3f',
  'Cho hàm đệ quy sau:
`void foo(int n) { if(n > 0) foo(n-1); }`
hãy cho biết nhận định nào sau đây đúng:

