);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'ed19e0fd-d29d-557a-a98e-54ade7cc01c1', '8f263c7b-e207-524d-a8fb-ff118fb23a3f',
  'Biết rằng duyệt tiền thứ tự một cây nhị phân cho kết quả là A,B,C,D,E,K,F,G, kết quả duyệt trung thứ tự là B,C,A,D,K,E,F,G. Hãy cho biết kết quả duyệt hậu thứ tự [3.5, 15]

