- (b) d-heap (heap mà mỗi node có d nhánh) thích hợp cho những ứng dụng mà số lượng thao tác chèn nhiều hơn so với xóa
- (c) Trong max-heap với n phần tử (n>=3), phần tử nhỏ nhất sẽ nằm ở nút lá
- (d) Trong 3 đáp án trên, có 2 đáp án là đúng', 6
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
