INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '6dd395d9-e39e-5d86-9266-902bbc7867d8', '8f263c7b-e207-524d-a8fb-ff118fb23a3f',
  'Dùng phương pháp sắp xếp chèn trực tiếp để tiến hành sắp xếp các dãy sau theo thứ tự tăng dần, hãy cho biết dãy nào cần số lần so sánh ít nhất. [6.4, 16]

