INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'd279c5c7-3d25-5a68-937b-2fcabe2150bb', '8f263c7b-e207-524d-a8fb-ff118fb23a3f',
  '9. Giả sử dùng mảng $A[0..m-1]$ để hiện thực hàng đợi vòng (circular queue), biết rằng vị trí của đầu và cuối là front và rear, thì [2.1, 14]
   (a) Có thể xảy ra trường hợp $rear < front$
   (b) Số lượng phần tử trong hàng đợi được tính theo công thức sau $(rear - front + m)\%m + 1$
   (c) Khi rear bằng $m - 1$ thì hàng đợi đầy
   (d) Trong 3 đáp án trên, có 2 đáp án đúng

Lựa chọn:
- (a) Có thể xảy ra trường hợp $rear < front$
- (b) Số lượng phần tử trong hàng đợi được tính theo công thức sau $(rear - front + m)\%m + 1$
- (c) Khi rear bằng $m - 1$ thì hàng đợi đầy
- (d) Trong 3 đáp án trên, có 2 đáp án đúng', 9
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '7ff2985d-871f-5302-94a0-3fd0fcc51f59', '8f263c7b-e207-524d-a8fb-ff118fb23a3f',
  'Sắp xếp dãy số sau $[15, 9, 7, 8, 20, -1, 4]$. Biết rằng sau một lần (one pass) sắp xếp, dãy số trên trở thành $[4, 9, -1, 8, 20, 7, 15]$, hãy cho biết phương pháp sắp xếp nào đã được sử dụng: [6.1, 18]

Lựa chọn:
- (a) Sắp xếp lựa chọn
- (b) Sắp xếp nhanh (Quick sort)
