INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'fb147a12-133d-521c-9967-ba20f7ffc535', '8f263c7b-e207-524d-a8fb-ff118fb23a3f',
  'Giả sử biểu diễn đồ thị có trọng số G bằng ma trận kề M, hãy cho biết nhận định nào sau đây là đúng:  
(a) Nếu M đối xứng qua đường chéo chính, thì G là đồ thị vô hướng, G không thể là đồ thị có hướng  
(b) Nếu M không đối xứng qua đường chéo chính, thì G là có thể là đồ thị vô hướng  
(c) Số cạnh của đồ thị chính là số lượng giá trị khác 0 trong ma trận G  
(d) Cả A, B và C đều sai

Lựa chọn:
- (a) Nếu M đối xứng qua đường chéo chính, thì G là đồ thị vô hướng, G không thể là đồ thị có hướng
- (b) Nếu M không đối xứng qua đường chéo chính, thì G là có thể là đồ thị vô hướng
- (c) Số cạnh của đồ thị chính là số lượng giá trị khác 0 trong ma trận G
- (d) Cả A, B và C đều sai', 12
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
